package a

import (
	"fmt"
	"strings"
	"testing"
)

func TestPass(t *testing.T) { t.Log("a log line of a passing test") }

func TestFail(t *testing.T) {
	t.Log("before the failure")
	t.Errorf("got %d, want %d", 1, 2)
}

// A parent that calls t.Skip after a subtest passed: the parent is a skip of its own.
func TestParentSkipAfterPass(t *testing.T) {
	t.Run("ok", func(t *testing.T) {})
	t.Skip("forbidden parent reason")
}

// Every subtest skips; one reason is allowed, two are not.
func TestMixedGroup(t *testing.T) {
	t.Run("x", func(t *testing.T) { t.Skip("allowed reason") })
	t.Run("y", func(t *testing.T) { t.Skip("forbidden y") })
	t.Run("z", func(t *testing.T) { t.Skip("forbidden z") })
}

// Three levels: TestNested3/b/c and TestNested3/d/e skip, so the whole tree is one group.
func TestNested3(t *testing.T) {
	t.Run("b", func(t *testing.T) {
		t.Run("c", func(t *testing.T) { t.Skip("allowed reason") })
	})
	t.Run("d", func(t *testing.T) {
		t.Run("e", func(t *testing.T) { t.Skip("allowed reason") })
	})
}

// A cleanup that prints a zero-indent "file.go:N:" line to stdout after the skip.
func TestStdoutAfterSkip(t *testing.T) {
	t.Cleanup(func() { fmt.Println("noise.go:1: printed by a cleanup") })
	t.Skip("allowed reason")
}

// A cleanup that logs after the skip: go prints its line after the t.Skip message and before
// the SKIP frame.
func TestCleanupLogAfterSkip(t *testing.T) {
	t.Cleanup(func() { t.Log("cleanup log line") })
	t.Skip("allowed reason")
}

// The same cleanup, guarded as main.go recommends.
func TestGuardedCleanupLog(t *testing.T) {
	t.Cleanup(func() {
		if !t.Skipped() {
			t.Log("cleanup log line")
		}
	})
	t.Skip("allowed reason")
}

// Stdout without a trailing newline, then the skip message on the same output line.
func TestStdoutNoNewline(t *testing.T) {
	fmt.Print("progress: 3/3")
	t.Skip("allowed reason")
}

// Stdout without a trailing newline, then SkipNow without a message.
func TestStdoutNoNewlineSkipNow(t *testing.T) {
	fmt.Print("partial output")
	t.SkipNow()
}

// A skip message whose second line looks like a log header.
func TestHeaderLikeContinuation(t *testing.T) {
	t.Skip("allowed reason\n    gen.go:12: generated by stringer")
}

// A skip message longer than test2json's 1024-byte line buffer.
func TestLongSkip(t *testing.T) {
	t.Skip("long " + strings.Repeat("a", 3000))
}

// A skip message longer than testreport keeps.
func TestHugeSkip(t *testing.T) {
	t.Skip("huge " + strings.Repeat("b", 10000))
}

// A skip message of 25 lines.
func TestManyLineSkip(t *testing.T) {
	lines := make([]string, 25)
	for i := range lines {
		lines[i] = fmt.Sprintf("line %d", i+1)
	}
	t.Skip(strings.Join(lines, "\n"))
}

func TestSkipNow(t *testing.T) { t.SkipNow() }

func TestLogThenSkipNow(t *testing.T) {
	t.Log("logged before SkipNow")
	t.SkipNow()
}

// Parallel subtests that skip: their output interleaves in the stream.
func TestParallel(t *testing.T) {
	for _, name := range []string{"p1", "p2", "p3"} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			t.Logf("%s starting", name)
			t.Skipf("allowed reason")
		})
	}
}
